export function area({ width, height } = {}) {
  if (width === undefined || height === undefined) {
    throw new TypeError("width and height are required");   // guard: bad input
  }
  if (!(width > 0) || !(height > 0)) {
    throw new RangeError("width and height must be positive");
  }
  return width * height;              // happy path stays flat
}
